import sys
import heapq

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        n = int(input[index])
        m = int(input[index + 1])
        index += 2
        weights = list(map(int, input[index:index + n]))
        index += n
        if m < n - 1:
            results.append("-1")
            continue
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                heapq.heappush(edges, (weights[i] + weights[j], i, j))
        total_cost = 0
        selected_edges = []
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1
                return True
            return False

        while len(selected_edges) < m:
            if not edges:
                results.append("-1")
                break
            cost, u, v = heapq.heappop(edges)
            if union(u, v):
                selected_edges.append((u + 1, v + 1))
                total_cost += cost
        else:
            results.append(str(total_cost))
            for u, v in selected_edges:
                results.append(f"{u} {v}")

    print("\n".join(results))

if __name__ == "__main__":
    main()
